1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
10	
11	/**
12	 * Rejects (409) a create-owner request that would join an existing household. Because the household
13	 * is now keyed on the computed {@code householdId} (a pure function of the normalized last name and
14	 * postcode, see {@link OwnerIdentity#householdId}), owners sharing a last name and postcode are the
15	 * same household. A second such owner reads as the same person re-entered — and is a household
16	 * duplicate — only when it also carries the same email (both absent counts as the same); a genuine
17	 * distinct household member, told apart by a differing email, is admitted. Declaring
18	 * {@code sharesHousehold} bypasses the block entirely, creating a declared household member.
19	 *
20	 * <p>Runs after {@link CheckIdentityUnique} (so an exact identity collision is still a 409 even when
21	 * {@code sharesHousehold} is set) and within the write transaction, comparing against the owners
22	 * persisted so far. A missing postcode carries no household, so it never collides here.
23	 */
24	public class CheckHouseholdUnique {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateHouseholdException {
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return; // declared household member — bypass the block
30	        }
31	        String postcode = request.getPostcode();
32	        if (postcode == null || postcode.isBlank()) {
33	            return; // no postcode -> no household to collide with
34	        }
35	        String householdId = OwnerIdentity.householdId(request.getLastName(), postcode);
36	        String email = normalizeEmail(request.getEmail());
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (Boolean.TRUE.equals(existing.getDeleted())) {
39	                continue; // soft-deleted owners are ignored by the household check
40	            }
41	            // A genuine distinct household member is told apart by a differing email; only a matching
42	            // email (both absent counts as matching) reads as the same person re-entered and is blocked.
43	            if (householdId.equals(existing.getHouseholdId())
44	                    && email.equals(normalizeEmail(existing.getEmail()))) {
45	                throw new DuplicateHouseholdException(householdId);
46	            }
47	        }
48	    }
49	
50	    /** Lower-cased email, or {@code ""} when absent/blank, so the comparison is case-insensitive. */
51	    private static String normalizeEmail(String email) {
52	        return (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
53	    }
54	}
