1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's {@code householdId}: a stable identifier shared by all owners who live in the
8	 * same household, i.e. share a last name and postcode. It is derived from the normalized last name and
9	 * postcode (see {@link OwnerIdentity#householdId}), so two owners in the same household
10	 * deterministically receive the same value without any lookup — the household is computed, never linked.
11	 *
12	 * <p>Runs after {@link BuildOwner} has mapped the request onto the entity and before
13	 * {@link SaveOwner}, so the assigned id is persisted and returned. It also feeds the derived
14	 * {@code identityKey} that {@link CheckIdentityUnique} uses for duplicate detection.
15	 */
16	public class AssignHouseholdId {
17	
18	    public void service(@Val Owner owner) {
19	        owner.setHouseholdId(OwnerIdentity.householdId(owner.getLastName(), owner.getPostcode()));
20	    }
21	}
