1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Assigns the owner's soft-duplicate signal. The pipeline only reaches this step once
10	 * {@link CheckIdentityUnique} and {@link CheckHouseholdUnique} have passed, so the new owner is never
11	 * a <em>hard</em> duplicate here. A declared household member (one that set {@code sharesHousehold})
12	 * is never a suspected duplicate — it deliberately shares its household — so it is left unflagged.
13	 * Otherwise, when it shares an existing owner's last name and postcode while carrying a
14	 * <em>different</em> telephone, it is flagged as a possible duplicate: {@code possibleDuplicate} true
15	 * with {@code possibleDuplicateOf} set to the matching owner's id. Otherwise {@code possibleDuplicate}
16	 * is false and {@code possibleDuplicateOf} is left null.
17	 *
18	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}, within the write transaction, so it
19	 * compares against the owners persisted so far (excluding this new, not-yet-saved one). The last name
20	 * is compared case-insensitively; a missing postcode can never match.
21	 */
22	public class AssignPossibleDuplicate {
23	
24	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
25	        owner.setPossibleDuplicate(false);
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return; // a declared household member is not a suspected duplicate
28	        }
29	        String lastName = owner.getLastName();
30	        String postcode = owner.getPostcode();
31	        String telephone = owner.getTelephone();
32	        if (postcode == null || postcode.isBlank()) {
33	            return;
34	        }
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (Boolean.TRUE.equals(existing.getDeleted())) {
37	                continue; // soft-deleted owners are ignored by the duplicate check
38	            }
39	            boolean sameLastName = lastName != null && lastName.equalsIgnoreCase(existing.getLastName());
40	            boolean samePostcode = postcode.equals(existing.getPostcode());
41	            boolean differentTelephone = telephone == null
42	                    ? existing.getTelephone() != null
43	                    : !telephone.equals(existing.getTelephone());
44	            if (sameLastName && samePostcode && differentTelephone) {
45	                owner.setPossibleDuplicate(true);
46	                owner.setPossibleDuplicateOf(existing.getId());
47	                return;
48	            }
49	        }
50	    }
51	}
