26	    /** Returns the normalized address, or {@code ""} when {@code value} is null or blank. */
27	    static String normalize(String value) {
28	        if (value == null || value.isBlank()) {
29	            return "";
30	        }
31	        String[] tokens = value.trim().toUpperCase().split("\\s+");
32	        StringBuilder sb = new StringBuilder(value.length());
33	        for (String token : tokens) {
34	            if (sb.length() > 0) {
35	                sb.append(' ');
36	            }
37	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
38	        }
39	        return sb.toString();
40	    }
